WITH lines AS (SELECT id, service, host, log_ts, latency_ms, status_code, key, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS key, v), with_windows AS (SELECT *, ROUND(latency_ms / SUM(latency_ms) OVER (PARTITION BY host), 4) AS latency_ms_share FROM lines WHERE status_code <> 335), base AS (SELECT id, host, log_ts, latency_ms, status_code, key, v, latency_ms_share, ROUND(latency_ms * 0.85, 2) AS adjusted_latency_ms, TRIM(service) AS clean_service, COALESCE(key, 'N/A') AS resolved_key FROM with_windows WHERE service NOT IN ('billing', 'checkout', 'auth')), with_windows_app_logs AS (SELECT *, MAX(latency_ms_share) OVER (PARTITION BY host, key ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW) AS latency_ms_share_max_2h, AVG(status_code) OVER (PARTITION BY key) AS key_avg_status_code, AVG(latency_ms_share) OVER (PARTITION BY host) AS host_avg_latency_ms_share FROM base), scored AS (SELECT host, latency_ms, key, v, adjusted_latency_ms, clean_service, resolved_key, latency_ms_share_max_2h, key_avg_status_code, host_avg_latency_ms_share, CUME_DIST() OVER (PARTITION BY MONTH(log_ts), key ORDER BY host_avg_latency_ms_share NULLS LAST) AS host_avg_latency_ms_share_cume_dist, MAX(latency_ms) OVER w_part AS latency_ms_max_1h FROM with_windows_app_logs WINDOW w_part AS (ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW)) SELECT key, PERCENTILE_APPROX(host_avg_latency_ms_share_cume_dist, 0.9) AS host_avg_latency_ms_share_cume_dist_p90, COUNT(DISTINCT key) AS distinct_keys, COUNT(*) FILTER (WHERE host = 'h1') AS h1_rows, AVG(latency_ms) AS avg_latency_ms, COUNT(*) AS row_count, COUNT(*) AS num_rows FROM scored GROUP BY key HAVING PERCENTILE_APPROX(host_avg_latency_ms_share_cume_dist, 0.9) > 0 ORDER BY distinct_keys DESC;
